// Profiler: shape, types, missingness, ranges, top values (plain JS)
function profile(rows) {
  const cols = Object.keys(rows[0] || {});
  const report = { rows: rows.length, cols: cols.length, columns: {} };
  for (const c of cols) {
    const vals = rows.map((r) => r[c]);
    const missing = vals.filter((v) => v == null || v === "").length;
    const nums = vals.filter((v) => typeof v === "number");
    report.columns[c] = {
      missing, missingRate: rows.length ? missing / rows.length : 0,
      min: nums.length ? Math.min(...nums) : null,
      max: nums.length ? Math.max(...nums) : null,
    };
  }
  return report;
}
